<script setup lang="ts">
import {ref,watch,computed} from 'vue';import {usePage} from '@inertiajs/vue3';import Pagination from './Pagination.vue';import LoadingState from './LoadingState.vue';import LoanChart from './LoanChart.vue';import {json,money,dateLabel} from '../lib/format';
const props=defineProps<{records:any;today:string}>();const page=usePage<any>();
const emit=defineEmits<{edit:[record:any];extra:[record:any];remove:[record:any];history:[record:any];payment:[id:string];correct:[record:any];removePayment:[record:any]}>();
const selected=ref<string>(),detail=ref<any>(),error=ref(''),loading=ref(false);let loadNumber=0;
async function load(url?:string){if(!selected.value)return;const number=++loadNumber;error.value='';loading.value=true;try{const result=await json(url||'/loans/'+selected.value);if(number===loadNumber)detail.value=result;}catch(e:any){if(number===loadNumber)error.value=e.message;}finally{if(number===loadNumber)loading.value=false;}}
watch(()=>props.records,()=>{const requested=new URL(page.url,window.location.origin).searchParams.get('loan');if(requested&&props.records.data.some((r:any)=>r.id===requested))selected.value=requested;if(!props.records.data.some((r:any)=>r.id===selected.value)){selected.value=props.records.data[0]?.id;detail.value=null;}load();},{immediate:true});
function select(id:string){selected.value=id;detail.value=null;load();}
const record=computed(()=>detail.value?{...detail.value.loan,account:detail.value.account,series:detail.value.series,next:props.records.data.find((r:any)=>r.id===selected.value)?.next}:null);
const progress=computed(()=>detail.value?.loan.repayment_total_cents?Math.min(100,Number(detail.value.summary.paid_cents)/Number(detail.value.loan.repayment_total_cents)*100):100);
</script>
<template><div class="grid items-start gap-5 lg:grid-cols-[240px_minmax(0,1fr)]"><div><button v-for="loan in records.data" :key="loan.id" class="workspace-selector" :aria-pressed="selected===loan.id" @click="select(loan.id)"><span class="font-medium">{{loan.account.name}}</span><span class="money mt-2 block text-xl">{{money(loan.account.balance_cents)}} <span class="help">owed</span></span><span class="help mt-2 block">{{loan.series_id?'Next '+dateLabel(loan.next?.due_date):'Balance tracking only'}}</span></button><Pagination :records="records"/></div><div v-if="selected" class="min-w-0 space-y-5" :aria-busy="loading"><p v-if="error" role="alert" class="panel p-5 text-warning">{{error}} <button class="underline" @click="load()">Try again</button></p><LoadingState v-if="!detail" :loading="loading" label="Loading loan" class="panel"/>
<div v-if="detail" class="space-y-5" :class="loading?'opacity-50 pointer-events-none':''"><section class="panel p-5"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-xl">{{detail.account.name}}</h2><p class="help mt-1">{{detail.loan.lender||'Manual loan'}} · {{detail.loan.series_id?detail.series.frequency.replaceAll('_',' '):'Balance tracking only'}}</p></div><div class="flex flex-wrap gap-2"><button class="btn" @click="emit('edit',record)">Edit loan</button><button v-if="detail.loan.series_id&&Number(detail.account.balance_cents)>0" class="btn-primary" @click="emit('extra',record)">Record extra payment</button><button class="btn" @click="emit('history',record)">History</button><button class="btn-danger" @click="emit('remove',record)">Delete</button></div></div><div class="mt-6 grid grid-cols-2 gap-5 lg:grid-cols-4"><div v-for="[label,value] in [['Remaining',money(detail.account.balance_cents)],['Paid so far',detail.loan.series_id?money(detail.summary.paid_cents):'—'],['Repayment total',detail.loan.series_id?money(detail.loan.repayment_total_cents):'—'],['Installment',detail.loan.series_id?money(detail.loan.installment_cents):'—']]" :key="label"><p class="help">{{label}}</p><p class="money mt-2 text-xl">{{value}}</p></div></div><template v-if="detail.loan.series_id"><div class="mt-5 h-2 overflow-hidden rounded bg-zinc-100" role="progressbar" :aria-valuenow="progress" aria-valuemin="0" aria-valuemax="100" aria-label="Loan repayment"><div class="h-2 bg-ink" :style="{width:progress+'%'}"/></div><p class="help mt-2">{{progress.toFixed(1)}}% repaid</p><div class="mt-4 flex flex-wrap gap-6 text-muted"><span>Next: {{dateLabel(detail.summary.next_date)}}</span><span>{{detail.summary.remaining_count}} payments left</span><span>Final: {{dateLabel(detail.summary.final_date)}}</span></div></template><p v-else class="help mt-5">Enable a repayment schedule in Edit loan to track installments and payments.</p><p v-if="detail.loan.notes" class="mt-4 whitespace-pre-wrap text-muted">{{detail.loan.notes}}</p></section>
<section class="panel p-5"><LoanChart :detail="detail" :today="today"/></section>
<section class="panel overflow-x-auto"><h3 class="px-5 py-4 font-medium">Recorded payments</h3><table><thead><tr><th>Date</th><th>Payment</th><th>Amount</th><th/></tr></thead><tbody><tr v-for="payment in detail.payments.data" :key="payment.id"><td>{{dateLabel(payment.payment_date)}}</td><td>{{payment.kind.replaceAll('_',' ')}}</td><td class="money">{{money(payment.amount_cents)}}</td><td><button v-if="payment.occurrence_id" class="btn" @click="emit('payment',payment.occurrence_id)">Manage payment</button><div v-else class="flex gap-2"><button class="btn" @click="emit('correct',{...payment,loan:record})">Correct</button><button class="btn-danger" @click="emit('removePayment',payment)">Delete</button></div></td></tr></tbody></table><p v-if="!detail.payments.data.length" class="px-5 py-8 text-muted">No payments recorded yet.</p><Pagination :records="detail.payments" asynchronous @load="load"/></section>
<section v-if="detail.installments" class="panel overflow-x-auto"><h3 class="px-5 py-4 font-medium">Installments</h3><table><thead><tr><th>Due</th><th>Amount</th><th>Status</th><th/></tr></thead><tbody><tr v-for="slot in detail.installments.data" :key="slot.id"><td>{{dateLabel(slot.due_date)}}</td><td class="money">{{money(slot.amount_cents)}}</td><td>{{slot.status==='paid'?'Paid '+dateLabel(slot.completed_date):slot.due_date<today?'Overdue':'Unpaid'}}</td><td><button class="btn" @click="emit('payment',slot.id)">{{slot.status==='paid'?'Manage payment':'Mark paid'}}</button></td></tr></tbody></table><Pagination :records="detail.installments" asynchronous @load="load"/></section></div></div><div v-else class="panel empty"><p>No loans match this view.</p><p class="help">Add a loan or include paid-off loans above.</p></div></div></template>
